def make_question(index, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+i), "text": text} for i, text in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題常見的聚落階層、交通網絡與服務可達性判讀能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u,t,l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」的聚落功能、距離、交通、服務、流量與受影響群體。", f"整理證據：分開節點功能、服務範圍、實際可達性與政策成本；核心理由是「{reason}」。", f"核對正解：選項 {aid}「{answer}」符合聚落網絡與空間選擇的判讀。", "排除誘答：檢查是否只看直線距離、人口、道路或總流量，並找出被忽略的時間、費用與公平。", "結論回查：確認空間尺度、時間序列與不同群體資料一致；交通條件改變時重新判斷。"]
    return {"id": f"question-social-content-geo-af-iv-1-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-geo-af-iv-1"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫聚落體系與交通網絡情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-af-iv-1", "examPatternRefs": refs, "solutionStrategy": "先找聚落節點與功能，再比較服務範圍、實際交通時間與流量，最後檢查建設帶來的便利、成本與公平。", "solutionSteps": steps}

for index, row in enumerate(DATA, 1):
    (OUT / f"question-social-content-geo-af-iv-1-{index}.json").write_text(json.dumps(make_question(index, row), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
